  1512      VerifyOrExit(aFrame != NULL, error = OT_ERROR_NO_FRAME_RECEIVED);
  1513      VerifyOrExit(mEnabled, error = OT_ERROR_INVALID_STATE);
  1514
  1515      // Ensure we have a valid frame before attempting to read any contents of
  1516      // the buffer received from the radio.
  1517      SuccessOrExit(error = aFrame->ValidatePsdu());
  1518
  1519      aFrame->GetSrcAddr(srcaddr);
  1520      aFrame->GetDstAddr(dstaddr);
  1521      neighbor = Get<Mle::MleRouter>().GetNeighbor(srcaddr);
  1522
  1523      // Destination Address Filtering
  1524      switch (dstaddr.GetType())
  1525      {
  1526      case Address::kTypeNone:
  1527          break;
  1528
  1529      case Address::kTypeShort:
  1530          aFrame->GetDstPanId(panid);
  1531          VerifyOrExit((panid == kShortAddrBroadcast || panid == mPanId) &&
  1532                           ((mRxOnWhenIdle && dstaddr.IsBroadcast()) || dstaddr.GetShort() == GetShortAddress()),
  1533                       error = OT_ERROR_DESTINATION_ADDRESS_FILTERED);
  1534
  1535          // Allow  multicasts from neighbor routers if FTD
  1536          if (neighbor == NULL && dstaddr.IsBroadcast() && Get<Mle::MleRouter>().IsFullThreadDevice())
  1537          {
  1538              neighbor = Get<Mle::MleRouter>().GetRxOnlyNeighborRouter(srcaddr);
  1539          }
  1540
  1541          break;
  1542
  1543      case Address::kTypeExtended:
  1544          aFrame->GetDstPanId(panid);
  1545          VerifyOrExit(panid == mPanId && dstaddr.GetExtended() == GetExtAddress(),
  1546                       error = OT_ERROR_DESTINATION_ADDRESS_FILTERED);
  1547          break;
  1548      }
  1549
  1550      // Source Address Filtering
  1551      switch (srcaddr.GetType())
  1552      {
  1553      case Address::kTypeNone:
  1554          break;
  1555
  1556      case Address::kTypeShort:
  1557          otLogDebgMac("Received frame from short address 0x%04x", srcaddr.GetShort());
  1558
  1559          if (neighbor == NULL)
  1560          {
  1561              ExitNow(error = OT_ERROR_UNKNOWN_NEIGHBOR);
  1562          }
  1563
  1564          srcaddr.SetExtended(neighbor->GetExtAddress());
  1565
  1566          // fall through
  1567
  1568      case Address::kTypeExtended:
  1569
  1570          // Duplicate Address Protection
  1571          if (srcaddr.GetExtended() == GetExtAddress())
  1572          {
  1573              ExitNow(error = OT_ERROR_INVALID_SOURCE_ADDRESS);
  1574          }
  1575
  1576  #if OPENTHREAD_CONFIG_MAC_FILTER_ENABLE
  1577
  1578          // Source filter Processing. Check if filtered out by whitelist or blacklist.
  1579          SuccessOrExit(error = mFilter.Apply(srcaddr.GetExtended(), rssi));
  1580
  1581          // override with the rssi in setting
  1582          if (rssi != OT_MAC_FILTER_FIXED_RSS_DISABLED)
  1583          {
  1584              aFrame->SetRssi(rssi);
  1585          }
  1586
  1587  #endif // OPENTHREAD_CONFIG_MAC_FILTER_ENABLE
  1588
  1589          break;
  1590      }
